CREATE TABLE sync_info(id INTEGER PRIMARY KEY CHECK(id=1),sync TEXT NOT NULL,account TEXT NOT NULL,remote_root TEXT NOT NULL,local_root BLOB NOT NULL,generation INTEGER NOT NULL CHECK(generation>0),initial_complete INTEGER NOT NULL CHECK(initial_complete IN(0,1)));
CREATE TABLE items(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,local_presence TEXT NOT NULL,remote_presence TEXT NOT NULL,status TEXT NOT NULL,conflict_reason TEXT,revision INTEGER NOT NULL CHECK(revision>0),last_checked INTEGER,last_synced INTEGER,local_id TEXT UNIQUE,remote_account TEXT,remote_id TEXT,UNIQUE(remote_account,remote_id),CHECK((remote_account IS NULL)=(remote_id IS NULL)));
CREATE INDEX items_status ON items(status,seq);
CREATE TABLE local_files(item TEXT PRIMARY KEY REFERENCES items(id),path BLOB NOT NULL UNIQUE,parent_path BLOB NOT NULL);
CREATE INDEX local_parent ON local_files(parent_path,item);
CREATE TABLE remote_files(item TEXT PRIMARY KEY REFERENCES items(id),provider TEXT NOT NULL);
CREATE TABLE remote_parents(item TEXT NOT NULL REFERENCES items(id),account TEXT NOT NULL,parent TEXT NOT NULL,PRIMARY KEY(item,parent));
CREATE INDEX remote_parent ON remote_parents(account,parent,item);
CREATE TABLE metadata_fields(item TEXT NOT NULL REFERENCES items(id),side INTEGER NOT NULL CHECK(side IN(0,1)),field TEXT NOT NULL,latest TEXT NOT NULL,known TEXT,PRIMARY KEY(item,side,field));
CREATE TABLE receipts(event TEXT PRIMARY KEY,item TEXT NOT NULL REFERENCES items(id),side INTEGER NOT NULL CHECK(side IN(0,1)),digest BLOB NOT NULL,proof TEXT NOT NULL);
CREATE TABLE operations(seq INTEGER PRIMARY KEY AUTOINCREMENT,item TEXT NOT NULL REFERENCES items(id),direction TEXT NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL,base_revision INTEGER NOT NULL CHECK(base_revision>0),expected_version TEXT,attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 4294967295),next_attempt INTEGER,last_error TEXT,created INTEGER NOT NULL,started INTEGER,completed INTEGER,dedup TEXT,fingerprint BLOB NOT NULL,UNIQUE(item,dedup),UNIQUE(seq,item));
CREATE INDEX operation_queue ON operations(state,next_attempt,seq);
CREATE INDEX operation_item ON operations(item,seq);
CREATE UNIQUE INDEX running_item ON operations(item) WHERE state='Running';
CREATE TABLE baselines(item TEXT NOT NULL REFERENCES items(id),side INTEGER NOT NULL CHECK(side IN(0,1)),presence TEXT NOT NULL,name TEXT,local_name BLOB,parent_local TEXT REFERENCES items(id),parent_account TEXT,parent_remote TEXT,version TEXT,checksum TEXT,size TEXT,modified INTEGER,confirmed INTEGER NOT NULL,PRIMARY KEY(item,side),CHECK((parent_account IS NULL)=(parent_remote IS NULL)));
CREATE TABLE activities(seq INTEGER PRIMARY KEY AUTOINCREMENT,item TEXT NOT NULL REFERENCES items(id),operation INTEGER,event_type TEXT NOT NULL,origin TEXT NOT NULL,outcome TEXT NOT NULL,occurred INTEGER NOT NULL,description TEXT,error_kind TEXT,item_name TEXT,remote_id TEXT,local_path BLOB,FOREIGN KEY(operation,item) REFERENCES operations(seq,item));
CREATE INDEX activity_time ON activities(occurred,seq);
CREATE INDEX activity_item ON activities(item,occurred,seq);
CREATE INDEX activity_operation ON activities(operation,occurred,seq);
CREATE TABLE confirmations(item TEXT NOT NULL REFERENCES items(id),revision INTEGER NOT NULL,digest BLOB NOT NULL,operation INTEGER REFERENCES operations(seq),activity INTEGER REFERENCES activities(seq),PRIMARY KEY(item,revision));
CREATE TABLE analyses(seq INTEGER PRIMARY KEY AUTOINCREMENT,item TEXT NOT NULL REFERENCES items(id),item_kind TEXT NOT NULL,base_revision INTEGER NOT NULL CHECK(base_revision>0),result_revision INTEGER NOT NULL CHECK(result_revision=base_revision+1),input_digest BLOB NOT NULL,request_digest BLOB NOT NULL,recorded INTEGER NOT NULL,disposition TEXT NOT NULL,baseline_confirmed INTEGER NOT NULL,local_complete INTEGER NOT NULL,remote_complete INTEGER NOT NULL,local_content TEXT NOT NULL,remote_content TEXT NOT NULL,current_content TEXT NOT NULL,local_parent TEXT,current_parents TEXT NOT NULL,UNIQUE(item,base_revision),UNIQUE(seq,item));
CREATE INDEX analysis_item ON analyses(item,seq);
CREATE INDEX analysis_disposition ON analyses(disposition,seq);
CREATE TABLE analysis_findings(analysis INTEGER NOT NULL REFERENCES analyses(seq),position INTEGER NOT NULL,origin TEXT NOT NULL,dimension TEXT NOT NULL,status TEXT NOT NULL,reason TEXT NOT NULL,PRIMARY KEY(analysis,position));
CREATE TABLE analysis_requirements(analysis INTEGER NOT NULL REFERENCES analyses(seq),position INTEGER NOT NULL,kind TEXT NOT NULL,PRIMARY KEY(analysis,position),UNIQUE(analysis,kind));
CREATE TABLE analysis_decisions(analysis INTEGER NOT NULL,item TEXT NOT NULL,position INTEGER NOT NULL,direction TEXT NOT NULL,kind TEXT NOT NULL,operation INTEGER NOT NULL UNIQUE,PRIMARY KEY(analysis,position),FOREIGN KEY(analysis,item) REFERENCES analyses(seq,item),FOREIGN KEY(operation,item) REFERENCES operations(seq,item));
CREATE TABLE item_associations(canonical TEXT PRIMARY KEY REFERENCES items(id),retired TEXT UNIQUE NOT NULL REFERENCES items(id),decision TEXT UNIQUE NOT NULL,local_digest BLOB NOT NULL,remote_digest BLOB NOT NULL,decided INTEGER NOT NULL);
CREATE TABLE analysis_plan_steps(analysis INTEGER NOT NULL REFERENCES analyses(seq),position INTEGER NOT NULL,method TEXT NOT NULL,command TEXT,PRIMARY KEY(analysis,position));
CREATE TABLE analysis_plan_blocks(analysis INTEGER NOT NULL,step INTEGER NOT NULL,position INTEGER NOT NULL,kind TEXT NOT NULL,PRIMARY KEY(analysis,step,position),FOREIGN KEY(analysis,step) REFERENCES analysis_plan_steps(analysis,position));
CREATE TABLE analysis_plan_dependencies(analysis INTEGER NOT NULL,step INTEGER NOT NULL,position INTEGER NOT NULL,item TEXT NOT NULL REFERENCES items(id),PRIMARY KEY(analysis,step,position),FOREIGN KEY(analysis,step) REFERENCES analysis_plan_steps(analysis,position));
CREATE TABLE analysis_plan_guards(analysis INTEGER NOT NULL REFERENCES analyses(seq),position INTEGER NOT NULL,item TEXT NOT NULL REFERENCES items(id),fingerprint BLOB NOT NULL,PRIMARY KEY(analysis,position));
CREATE TABLE analysis_plan_manual(analysis INTEGER NOT NULL REFERENCES analyses(seq),position INTEGER NOT NULL,reason TEXT NOT NULL,PRIMARY KEY(analysis,position));
CREATE TABLE analysis_plan_resources(analysis INTEGER NOT NULL,issue INTEGER NOT NULL,position INTEGER NOT NULL,resource TEXT NOT NULL,PRIMARY KEY(analysis,issue,position),FOREIGN KEY(analysis,issue) REFERENCES analysis_plan_manual(analysis,position));
CREATE TABLE analysis_plans(analysis INTEGER PRIMARY KEY REFERENCES analyses(seq));
CREATE TABLE analysis_plan_namespaces(analysis INTEGER NOT NULL REFERENCES analyses(seq),position INTEGER NOT NULL,directory TEXT NOT NULL,fingerprint BLOB NOT NULL,PRIMARY KEY(analysis,position));
PRAGMA user_version=5;
